import { hash as argonHash, verify as argonVerify } from '@node-rs/argon2'
import { COMMON_PASSWORDS } from './common-passwords'

/**
 * Password hashing and policy (SEC-P01 to SEC-P05).
 *
 * Argon2id with memory 19 MiB, 2 iterations, parallelism 1, and a unique salt per hash (the salt is
 * generated by the library and embedded in the PHC string). The algorithm identifier is stored
 * alongside the hash so parameters can be upgraded (SEC-P05). A plaintext password is never logged,
 * cached, or placed in an error message (SEC-P02): the functions here take it and return only a hash
 * or a boolean.
 *
 * bcrypt cost 12 is the documented fallback (SEC-P01, D-006) if Argon2 ever fails to install on a
 * platform; it is not wired now because @node-rs/argon2 ships prebuilt binaries. verifyPassword
 * dispatches on the stored algo so a fallback can be added without touching call sites.
 */
// algorithm 2 is Algorithm.Argon2id. The value is used directly rather than the const enum, which
// `isolatedModules` (Next.js) forbids referencing across module boundaries.
const ARGON2ID_OPTIONS = {
  algorithm: 2, // Algorithm.Argon2id
  memoryCost: 19456, // KiB = 19 MiB (SEC-P01: memory 19 MiB or higher)
  timeCost: 2, // 2 iterations
  parallelism: 1,
} as const

export const PASSWORD_ALGO = 'argon2id'
export const PASSWORD_MIN_LENGTH = 12 // SEC-P04

export type PasswordPolicyError = 'too_short' | 'too_common'

/**
 * SEC-P04: minimum length 12 and not a known-common password. No composition rules that force
 * symbols; length plus a breach check is stronger.
 */
export function checkPasswordPolicy(password: string): PasswordPolicyError | null {
  if (password.length < PASSWORD_MIN_LENGTH) return 'too_short'
  if (COMMON_PASSWORDS.has(password.toLowerCase())) return 'too_common'
  return null
}

export type HashedPassword = { hash: string; algo: string }

/** SEC-P01: hash with Argon2id, returning the hash and the algorithm identifier to store with it. */
export async function hashPassword(password: string): Promise<HashedPassword> {
  const hashed = await argonHash(password, ARGON2ID_OPTIONS)
  return { hash: hashed, algo: PASSWORD_ALGO }
}

/**
 * Verify a password against a stored hash. Returns false on any mismatch or malformed hash; never
 * throws for a wrong password (SEC-P02, SEC-S05 generic outcome). Throws only for an algorithm the
 * build does not support, which is a programming error, not a login attempt.
 */
export async function verifyPassword(storedHash: string, algo: string, password: string): Promise<boolean> {
  if (algo !== PASSWORD_ALGO) {
    throw new Error(`Unsupported password algorithm: ${algo}`)
  }
  try {
    return await argonVerify(storedHash, password, ARGON2ID_OPTIONS)
  } catch {
    return false
  }
}

/**
 * SEC-P05: re-hash on login when the stored parameters are weaker than the current ones. Parses the
 * Argon2 PHC string ($argon2id$v=19$m=19456,t=2,p=1$...). An unknown algo or unparseable hash is
 * treated as needing a re-hash.
 */
export function needsRehash(storedHash: string, algo: string): boolean {
  if (algo !== PASSWORD_ALGO) return true
  const match = storedHash.match(/\$argon2id\$v=\d+\$m=(\d+),t=(\d+),p=(\d+)\$/)
  if (!match) return true
  const memory = Number(match[1] ?? '0')
  const time = Number(match[2] ?? '0')
  const parallelism = Number(match[3] ?? '0')
  return (
    memory < ARGON2ID_OPTIONS.memoryCost ||
    time < ARGON2ID_OPTIONS.timeCost ||
    parallelism < ARGON2ID_OPTIONS.parallelism
  )
}
